async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
  const headers = new Headers(init.headers);
  headers.set('Accept', 'application/json');
  if (init.body && !(init.body instanceof FormData) && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }
  const method = (init.method || 'GET').toUpperCase();
  const csrfToken = readCsrfToken();
  if (!['GET', 'HEAD', 'OPTIONS'].includes(method) && csrfToken) {
    headers.set('X-CSRF-Token', csrfToken);
  }

  const response = await fetch(`${API_BASE_URL}${path}`, {
    ...init,
    headers,
    credentials: 'same-origin',
  });
  if (!response.ok) throw await parseError(response);
  if (response.status === 204) return undefined as T;
  return response.json() as Promise<T>;
}

/**
 * Parse an SSE response without assuming that network chunks align with lines.
 * The parser follows the event-stream field rules, including multi-line data,
 * comments/heartbeats, CRLF and a final event without a trailing blank line.
 */
export async function parseServerSentEvents(
  response: Response,
  onEvent: (event: ServerSentEvent) => void,
): Promise<void> {
  if (!response.body) throw new ApiError('스트리밍 응답 본문이 없습니다.', 502);
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let eventName: string | undefined;
  let eventID: string | undefined;
  let retry: number | undefined;
  let data: string[] = [];

  const dispatch = () => {
    if (data.length === 0) {
      eventName = undefined;
      retry = undefined;
      return;
    }
    onEvent({ event: eventName, id: eventID, retry, data: data.join('\n') });
    eventName = undefined;
    retry = undefined;
    data = [];
  };

  const consumeLine = (line: string) => {
    if (line === '') {
      dispatch();
      return;
    }
    if (line.startsWith(':')) return;
    const separator = line.indexOf(':');
    const field = separator === -1 ? line : line.slice(0, separator);
    let value = separator === -1 ? '' : line.slice(separator + 1);
    if (value.startsWith(' ')) value = value.slice(1);
    switch (field) {
      case 'event': eventName = value; break;
      case 'data': data.push(value); break;
      case 'id':
        if (!value.includes('\0')) eventID = value;
        break;
      case 'retry':
        if (/^\d+$/.test(value)) retry = Number(value);
        break;
      default:
        // Unknown fields are allowed by the SSE specification.
        break;
    }
  };

  while (true) {
    const { done, value } = await reader.read();
    buffer += decoder.decode(value, { stream: !done });
    while (true) {
      const lf = buffer.indexOf('\n');
      const cr = buffer.indexOf('\r');
      const index = lf === -1 ? cr : cr === -1 ? lf : Math.min(lf, cr);
      if (index === -1) break;
      if (buffer[index] === '\r' && index === buffer.length - 1 && !done) break;
      const width = buffer[index] === '\r' && buffer[index + 1] === '\n' ? 2 : 1;
      consumeLine(buffer.slice(0, index));
      buffer = buffer.slice(index + width);
    }
    if (done) break;
  }
  if (buffer) consumeLine(buffer);
  dispatch();
}

function decodeJSONEvent(sse: ServerSentEvent): AgentRunEvent | null {
  if (sse.data.trim() === '[DONE]') return null;
  try {
    const parsed = JSON.parse(sse.data) as unknown;
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      const value = parsed as Record<string, unknown>;
      return {
        ...value,
        type: String(value.type || sse.event || 'delta') as AgentRunEventType,
        ...(sse.id && value.eventId === undefined ? { eventId: sse.id } : {}),
      };
    }
    return { type: (sse.event || 'delta') as AgentRunEventType, data: parsed };
  } catch {
    return { type: (sse.event || 'delta') as AgentRunEventType, delta: sse.data };
  }
}

async function parseStream(
  response: Response,
  onDelta: (delta: string) => void,
  onEvent?: (event: Record<string, unknown>) => void,
): Promise<void> {
  await parseServerSentEvents(response, (sse) => {
    const event = decodeJSONEvent(sse);
    if (!event) return;
    onEvent?.(event);
    if (event.type === 'error') {
      throw new ApiError(String(event.message || 'AI 제공자 스트림이 중단되었습니다.'), 502, event);
    }
    const value = event.delta ?? event.content ?? event.text;
    if (typeof value === 'string' && value) onDelta(value);
  });
}

function streamingHeaders(): Record<string, string> {
  const csrfToken = readCsrfToken();
  return {
    Accept: 'text/event-stream',
    'Content-Type': 'application/json',
    ...(csrfToken ? { 'X-CSRF-Token': csrfToken } : {}),
  };
}

async function streamAgentResponse(
  response: Response,
  onEvent: (event: AgentRunEvent) => void,
): Promise<void> {
  if (response.status === 204) {
    onEvent({ type: 'done' });
    return;
  }
  const contentType = response.headers.get('Content-Type') || '';
  if (!contentType.includes('text/event-stream')) {
    const raw = await response.text();
    const payload = raw ? JSON.parse(raw) as Record<string, unknown> : {};
    const event = {
      ...payload,
      type: String(payload.type || 'done') as AgentRunEventType,
    };
    onEvent(event);
    return;
  }
  let streamedError: AgentRunEvent | null = null;
  await parseServerSentEvents(response, (sse) => {
    const event = decodeJSONEvent(sse);
    if (!event) return;
    onEvent(event);
    if (event.type === 'error') {
      streamedError = event;
    }
  });
  if (streamedError) {
    const error = streamedError as AgentRunEvent;
    throw new ApiError(String(error.message || error.error || '에이전트 실행이 중단되었습니다.'), 502, error);
  }
}

